#!/usr/bin/env python3
"""Populate the approved BB upgrade DAG through the pinned bd CLI only."""
import json
import re
import subprocess
from pathlib import Path

ROOT = Path('/home/ubuntu/Projects/pi-durable-bb-adapter')
BD = ['/home/ubuntu/.local/bin/bd', '-C', str(ROOT), '--db', str(ROOT / '.beads/beads.db'), '--sandbox']
PLAN = (ROOT / 'docs/plans/bb-durable-final-plan.md').read_text()
SECTIONS = {int(n): text for n, text in re.findall(r'^## [^\n]*\(BB(\d)\)\n(.*?)(?=^## |\Z)', PLAN, re.M | re.S)}
assert set(SECTIONS) == set(range(10))
COMMON = '''\n\nStanding boundaries: coordinator owns all bd writes; Leads read bd --readonly --sandbox, load pi-beads-lead and pi-durable-lead skills and applicable AGENTS, implement directly, acquire their own narrow exclusive Agent Mail leases, and return needs_checks. No nested delegation: coordinator arranges distinct reviewer and QA actors. Atomic own-path commits are authorized after checks and a short exclusive Git-index lease; only coordinator publishes to the verified private remote. No deploy/production restart/live SQLite/installed dist edits/Pocket changes. Only synthetic private data roots/sockets. Preserve managed 0.2.29 fixes and SDK 1.2.0. Fingerprint exact final candidate; changed candidate invalidates old verdict. Missing required gates remain blocked, never PASS. Report activation identity, exact owned paths, commands/exit codes/evidence and next action. Current permissions/runtime/model decisions are recorded in canonical preflight issue notes; reread them before dispatch.\n'''

def run(*args):
    p = subprocess.run(BD + list(args), text=True, capture_output=True)
    if p.returncode:
        raise RuntimeError(p.stderr + p.stdout)
    return p.stdout

existing = {x['id'] for x in json.loads(run('--readonly', 'list', '--all', '--limit', '0', '--json'))}

def issue(key, title, body, deps=(), parent='bbup-goal', kind='task', priority='1', labels='bb-upgrade', acceptance=None):
    ident = 'bbup-' + key
    if ident in existing:
        print('exists', ident, flush=True)
        return
    args = ['create', '--id', ident, '--title', title, '--type', kind, '--priority', priority, '--labels', labels, '--description', body + COMMON, '--acceptance', acceptance or 'Scope outcome verified on exact candidate; fresh evidence linked; required independent review and QA completed; deviations and unavailable gates explicitly reported.']
    if deps:
        args += ['--deps', ','.join('bbup-' + x for x in deps)]
    run(*args)
    if parent:
        run('dep', 'add', ident, parent, '--type', 'parent-child')
    existing.add(ident)
    print('created', ident, flush=True)

issue('goal', 'BB Durable: verified upgraded adapter, terminal preserved', PLAN, parent=None, kind='epic', priority='0', acceptance='BB0-BB6 and BB8-BB9 accepted with real unit/live/perf and independent review/QA evidence; BB7 only if explicitly enabled. Native BB child is same Durable conversation with one execution; terminal preserved; Pocket/live data untouched. Activation requires separate authorization.')
issue('runtime', 'Preflight: admit execution surface, models and continuation ownership', 'Operator admitted Pocket subagents; coordinator owns continuation and all tracker writes. Sol 6.1 medium or Luna high Leads, Gemini 3.8 Flash QA where actual runtime admits it, admitted free models for bounded simple work. Verify actual registry, not merely BB catalog: Pocket rejected Gemini, current inventory QA uses explicitly disclosed approved Luna pool. Scope and current schedule are in scope.md; a timer is not proof of unattended completion. Each child must report requested versus actually exposed model telemetry; no silent runtime/model fallback.', priority='0', kind='decision')
issue('authority', 'Preflight: BB core port scope and overnight operator review gates', 'Operator approved minimal isolated BB core/SDK patch if no supported registration port exists, and overnight local acceptance after independent review/QA without waiting for human video review. Preserve screenshot/video artifacts and every required unit/live/perf gate. Production activation/deploy/restart remain prohibited. This administrative approval is not technical acceptance of the BB1 port. Later explicit private-repository grant covers inspected own-change backup only; see scope.md.', priority='0', kind='decision')
issue('source', 'Preflight: admit source-controlled local candidate layout', 'Operator approved isolated candidates/provider and candidates/host from read-only installed managed provider /home/ubuntu/.local/share/pi-durable/bb-provider-shared-0.2.29 and host /home/ubuntu/.local/share/pi-durable/host. Preserve actual managed fixes, module resolution and donor fingerprints. Later operator request explicitly authorizes private Git repository and atomic own-change checkpoints. Never replace installed source/dist or copy live stores. Original plan/instructions remain baseline inputs; later grants are in scope.md and canonical issue notes.', priority='0', kind='decision')

issue('git', 'Private repository and atomic own-change checkpoints', 'Operator explicitly requested private GitHub Diffuzmetall/pi-durable-bb-adapter. Coordinator owns exclusions, scope.md, inspected atomic planning commits and private backup publication. Leads stage only verified own paths under short Git-index lease, never push. Do not include live DB, test data, dependencies or secrets. No force/history rewrites.', priority='0', acceptance='Remote is verified private; cohesive explicit-path commits inspected for secrets; local and remote commit IDs agree; runtime stores/Dolt internals/dependencies remain excluded.')
issue('7-enable', 'Decide optional BB7 adapter enablement', 'BB7 remains default-off and outside required BB9 acceptance until explicitly enabled after core gates. Coordinator records enable/disable choice and exact admitted adapters before dispatch; neither an available donor nor a ready issue enables code.', kind='decision', labels='bb-upgrade,optional', acceptance='Explicit enablement/disablement recorded; disabled adapters remain disabled and are not claimed tested.')

specs = {
0: [('inventory', 'Pin managed source provenance and reproducible candidate', 'Read-only source/manifests/resolution audit then authorized isolated candidate. Own candidate-manifest.json and baseline source inventory; coordinator records arm-program scope.md; preserve 0.2.29 managed fixes and foreign diffs. No tests/build from docs-only root.', ['source']), ('boot', 'Restrict readable paths and prove exact private Durable entrypoint', 'After independently accepted inventory, minimally harden sandbox readable paths and re-expose only audited source/dependency closure read-only. Use private sentinels for negative visibility/EROFS probes; no live credential reads or donor canaries. Run the actual existing Durable main/launcher with fresh private SQLite/socket/faux configuration, explicit ready condition and owned shutdown. Generic coding-agent root remains unsupported until separately migrated; no compatibility shim or coherent SDK 1.2 claim. No full tests/build/doctor/perf/plugin/model calls before this distinct review/QA checkpoint is accepted.', ['0-inventory']), ('baseline', 'Reproduce baseline with private store and regression harness', 'After accepted private boot checkpoint, own baseline.json and isolated boot/test fixture. Run existing archived upgrade-background-contract.test.mjs and upgrade-sdk-resources.test.mjs against admitted source; provider test/build from real scripts; private socket and synthetic histories. Retain raw cold/warm baseline and 30 alternating warm sample recipe.', ['0-boot'])],
1: [('port', 'Prove supported native BB projection port without prompt', 'Read current BB SDK/thread service. Produce exact public contract and authorization/idempotency evidence. No direct SQL or prompt fallback. If missing, return minimal core/SDK patch request and block native projection until admitted/tested.', ['0-check']), ('projection', 'Register existing Durable child once through supported port', 'Own provider src/host/subthread-spawner.ts, src/host/native-child-binding.ts and native-child-binding.test.ts. On unavailable/version-mismatched port fail closed. Duplicate event creates one BB child and never submits model input; rights and parent tuple tested.', ['1-port','authority'])],
2: [('anchor', 'Anchored background spawn and one Reporter', 'Own host durable/subagent.ts, subagents/tasks.ts, documents.ts and background.test.mjs initially. Port reviewed Pocket Anchor/Reporter to SDK 1.2 output shape, stable admission request IDs, explicit foreground; Stop foreground-only versus selected child versus whole anchored family are distinct; names/roles/tools/env limits. Agree public descriptor before provider integration. Prove gated-child/parent-free and admission crash/reopen.', ['0-check']), ('courier', 'Durable Courier batch, hold and delivery recovery', 'After anchor checkpoint, own subagents/delivery.ts and narrow background test updates. Retain result batches across idle/abort/budget hold and crash between persistence/ack. One report/delivery, no busy loop or second scheduler. Coordinate shared files with anchor owner.', ['2-anchor'])],
3: [('binding', 'Persistent scoped binding and recovery reconciliation', 'Own provider native-child-binding.ts and native-child-reconnect.test.ts after BB1 handoff. Durable tuple backend/session/conversation/BB-thread, trusted requester checks before history/side effects, crash after BB create before persistence reconciles one record. No process-local Map identity.', ['1-check','2-check']), ('controls', 'Attach history and route controls to exact child', 'Own provider src/runner/shared-host.ts and host durable/shared-server.ts/shared-commands.ts plus scoped reconnect tests. Serialize shared host files. Late/fast/finished child opens without prompt after task graph removal; stop/steer/follow-up target exact selected conversation; forged/revoked/stale denied.', ['3-binding'])],
4: [('graph', 'Truthful graph snapshots, waiting and completing', 'Own provider src/runner/task-graph-bridge.ts, src/host/delta-translator.ts and their tests. Pending/running/waiting/completing/abort-requested metadata preserved; waiting/completing never terminal success. Authoritative empty clears rows; stale events cannot overwrite fresh snapshots; disconnect is unknown. Descriptor grouping integration follows BB2 descriptor, not a blocker for initial state translation. Hand off delta-translator ownership explicitly to BB8 responsive work after this gate; never concurrent writes.', ['0-check'])],
5: [('loader', 'SDK 1.2 resource discovery with explicit trust', 'Own host durable/pi-extensions/loader.ts and loader.test.mjs. Use actual published SDK 1.2 DefaultResourceLoader aliases, local package/settings discovery and synthetic dirs. Reject untrusted before initializer, no fallback to coding-agent 1.0.2; retain origin/license.', ['0-check']), ('catalog', 'Resource catalog, enabled state and single-owner integration', 'Own host durable/pi-extensions/catalog.ts/catalog.test.mjs and serialize runtime.ts edits. Integrate admitted loader; distinguish loaded/disabled/error/unsupported, reject native tool conflicts, never second MCP connector/CodeMode/subagent owner. Agree registry/hook ports bidirectionally with BB6 before shared runtime/context integration.', ['5-loader'])],
6: [('hooks', 'Conversation-scoped hooks and direct/nested guard effects', 'Own host durable/pi-extensions/tool-bridge.ts/events.ts/context.ts and extension-contract.test.mjs. Implement real hook argument/result transforms, cancellation and lifecycle targeting without second AgentSession/transcript. Direct and nested CodeMode share guards; sibling contexts isolated. Agree context contract with BB2/3 before controls integration.', ['5-check']), ('commands', 'Commands and correlated UI approvals', 'After hook checkpoint, own narrow commands/UI additions under pi-extensions and tests. Approval actually waits, resolves same requester and same pending request, cancellation is real. Unsupported terminal UI/session APIs refuse explicitly. Serialize context/tool-bridge changes.', ['6-hooks']), ('reload', 'Transactional registry reload with active background policy', 'Own reload module/tests and serialized registry integration. Failed candidate preserves previous registry, disposes resources, retains task/document definitions and respects live background work. Factory external side effects are not claimed rolled back.', ['6-commands'])],
7: [('history', 'Optional conversation-scoped history adapter', 'Own host durable/adapters/manifest.ts/search-history.ts/contracts.test.mjs. Accept reviewed adapter separately with SDK 1.2/capability manifest, bounded lookup, own marker found and foreign marker absent. Default-off other candidates; no second DB.', ['2-check','6-check','7-enable']), ('mail', 'Optional guarded Agent Mail identity adapter', 'Own host durable/adapters/agent-mail.ts/README.md and narrow contract tests. Reuse existing guarded Mail transport with requester binding/revocation, hidden tool and unsafe replay tests. No second connector; Pocket wake unsupported capabilities fail before watchers. Keep DCG, Context execute/fetch, profiles/budgets/schedules/Jobs disabled unless separately admitted.', ['7-history'])],
8: [('events', 'Native BB child state and control presentation', 'Own verified provider UI entrypoints, src/runner/bridge/bb-child-event-adapter.ts and native-ui-events.test.ts. Native sidebar/transcript, roles/background/connection/approval and real usage or unavailable, scoped Open/Stop/Steer/Follow-up. No iframe/new dashboard; no second execution for Continue.', ['3-check','4-check','6-check']), ('responsive', 'Responsive streams and preserved scroll/focus', 'Own narrow final UI delta-translator changes and isolated UI harness only after explicit BB4 owner handoff and fresh reservation. Buffer presentation only, never drop committed history or delay terminal/control ack. Stress 3 concurrent children and long transcript; focus/draft/manual scroll preserved; accessibility and console/network checks.', ['8-events'])],
9: [('integrate', 'Exact final candidate regression and cross-feature integration', 'Own release manifest and isolated integration fixtures, not production. All required earlier gates accepted; full provider suite/build, target host tests, same-session native children/background/guards/history/terminal, crash/reopen at named boundaries. Optional BB7 tested only if enabled. Every result linked to same final fingerprint.', ['1-check','2-check','3-check','4-check','5-check','6-check','8-check']), ('rollback', 'Rollback artifact and restore parity runbook', 'Own candidate rollback artifact/runbook and private restore fixture. Rehearse rollback to BB0 baseline only on test store, preserve schemas/tasks/documents/models/skills/settings and MCP guards. No real migration/switch/restart. Record separate request for production activation only after final evidence.', ['9-integrate'])]
}

for n in range(10):
    issue(f'{n}', f'BB{n}: milestone acceptance', SECTIONS[n], kind='epic', priority='0' if n == 0 else '1', labels='bb-upgrade' + (',optional' if n == 7 else ''))
    for key, title, scope, deps in specs[n]:
        if n == 0 and key == 'inventory':
            deps = deps + ['runtime']
        issue(f'{n}-{key}', f'BB{n}: {title}', 'ASSIGNED SLICE\n' + scope + '\n\nFULL MILESTONE CONTRACT (this subtask does not replace whole-unit acceptance):\n' + SECTIONS[n], deps, parent=f'bbup-{n}', labels='bb-upgrade,implementation' + (',optional' if n == 7 else ''))
    final = f'{n}-{specs[n][-1][0]}'
    issue(f'{n}-check', f'BB{n}: independent review + live/perf QA acceptance gate', 'Coordinator arranges TWO DISTINCT supporting actors on exact final fingerprint: read-only review of code/security/contracts, and separate behavioral QA (unit/live/perf). Implementing Lead fixes findings and returns fresh affected checks; coordinator alone records bd acceptance. Collect all 10 specialized lanes, raw baseline/candidate samples (30 warm), tests.xml, outcome.json and fingerprints. BB0 has no operator-review gate. For BB1-BB9 use current canonical authority notes: operator waived human video wait, not independent checks or technical evidence. Missing UI/model/port/provenance gates block closure, other independent lanes proceed. Review/QA may overlap on read-only artifacts, not shared browser/test resources.\n\n' + SECTIONS[n], [final] + ([] if n == 0 else ['authority']), parent=f'bbup-{n}', labels='bb-upgrade,acceptance' + (',optional' if n == 7 else ''), acceptance='Distinct reviewer and QA receipts match final fingerprint. All required unit/live/perf, screenshot/video and budgets in this milestone contract passed. ' + ('BB0 has no operator-review gate. ' if n == 0 else 'Human review timing follows explicit canonical authority notes. ') + 'No unresolved failed/unavailable required gate; source/output fingerprints and evidence retained.')
print('Seed complete:', len(existing), 'issues', flush=True)
